sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {

    var complaint_recipient_value = current.getValue('recipient_of_this_complaint');

    var gr = new GlideRecord('sys_choice');

    gr.addQuery('name', 'x_hccc_hoc_ohs_investigation_case');
    gr.addQuery('element', 'recipient_of_this_complaint');
    gr.addQuery('language', 'en');
    gr.addQuery('value', complaint_recipient_value);
    gr.query();

    if (gr.next()) {
        var recipient_en = gr.getValue('label');

        template.print(recipient_en);
    }


})(current, template, email, email_action, event);
